query IssueCards($owner: String!, $repo: String!, $comments: Int!, $status: String!, $n0: Int!, $n1: Int!, $n2: Int!, $n3: Int!, $n4: Int!, $n5: Int!, $n6: Int!, $n7: Int!, $n8: Int!, $n9: Int!, $n10: Int!, $n11: Int!, $n12: Int!, $n13: Int!, $n14: Int!, $n15: Int!, $n16: Int!, $n17: Int!, $n18: Int!, $n19: Int!) {
  repository(owner: $owner, name: $repo) {
    i0: issueOrPullRequest(number: $n0) { ...card }
    i1: issueOrPullRequest(number: $n1) { ...card }
    i2: issueOrPullRequest(number: $n2) { ...card }
    i3: issueOrPullRequest(number: $n3) { ...card }
    i4: issueOrPullRequest(number: $n4) { ...card }
    i5: issueOrPullRequest(number: $n5) { ...card }
    i6: issueOrPullRequest(number: $n6) { ...card }
    i7: issueOrPullRequest(number: $n7) { ...card }
    i8: issueOrPullRequest(number: $n8) { ...card }
    i9: issueOrPullRequest(number: $n9) { ...card }
    i10: issueOrPullRequest(number: $n10) { ...card }
    i11: issueOrPullRequest(number: $n11) { ...card }
    i12: issueOrPullRequest(number: $n12) { ...card }
    i13: issueOrPullRequest(number: $n13) { ...card }
    i14: issueOrPullRequest(number: $n14) { ...card }
    i15: issueOrPullRequest(number: $n15) { ...card }
    i16: issueOrPullRequest(number: $n16) { ...card }
    i17: issueOrPullRequest(number: $n17) { ...card }
    i18: issueOrPullRequest(number: $n18) { ...card }
    i19: issueOrPullRequest(number: $n19) { ...card }
  }
}

fragment card on IssueOrPullRequest {
      __typename
      ... on Issue {
        id
        number
        title
        state
        stateReason(enableDuplicate: true)
        url
        createdAt
        closedAt
        author { login }
        body
        milestone { title dueOn }
        labels(first: 20) { totalCount nodes { name } }
        assignees(first: 10) { totalCount nodes { login } }
        comments(last: $comments) {
          totalCount
          nodes { id author { login } createdAt viewerDidAuthor body }
        }
        blockedBy(first: 20) { totalCount nodes { ...link } }
        blocking(first: 20) { totalCount nodes { ...link } }
        parent { ...link }
        subIssues(first: 20) { totalCount nodes { ...link } }
        subIssuesSummary { total completed }
        projectItems(first: 20) {
          totalCount
          nodes {
            id
            isArchived
            createdAt
            project { id }
            status: fieldValueByName(name: $status) { ...value }
            fieldValues(first: 100) { totalCount nodes { ...value } }
          }
        }
        timelineItems(last: 20, itemTypes: [PROJECT_V2_ITEM_STATUS_CHANGED_EVENT]) {
          totalCount
          nodes {
            ... on ProjectV2ItemStatusChangedEvent {
              createdAt
              previousStatus
              status
              wasAutomated
              actor { login }
              project { id }
            }
          }
        }
      }
    }

fragment link on Issue {
  number
  title
  state
  repository { nameWithOwner }
  projectItems(first: 10) {
    totalCount
    nodes {
      isArchived
      project { id }
      status: fieldValueByName(name: $status) {
        ... on ProjectV2ItemFieldSingleSelectValue { name field { ... on ProjectV2FieldCommon { id } } }
      }
    }
  }
}

fragment value on ProjectV2ItemFieldValue {
  __typename
  ... on ProjectV2ItemFieldSingleSelectValue { name field { ...field } }
  ... on ProjectV2ItemFieldIterationValue { title iterationId startDate duration field { ...field } }
  ... on ProjectV2ItemFieldTextValue { text field { ...field } }
  ... on ProjectV2ItemFieldNumberValue { number field { ...field } }
  ... on ProjectV2ItemFieldDateValue { date field { ...field } }
}

fragment field on ProjectV2FieldCommon { id name dataType }

